// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 amount, bytes calldata data) public {
        BalanceProbe probe = new BalanceProbe();
        vm.assume(amount > 0);
        vm.deal(address(c), amount);
        uint256 beforeBal = address(probe).balance;
        vm.prank(address(this));
        c.sendMoney(address(probe), amount, data);
        uint256 afterBal = address(probe).balance;
        assertTrue(afterBal == beforeBal + amount);
    }
}

contract BalanceProbe {
    fallback() external payable {}
}
